<span class="eyebrow">04 · SPACE & PERSPECTIVE</span><h3>A little more context.</h3><div class="form-grid"><label class="field"><span>Land area (optional, in the selected unit)</span><input name="land_area" type="number" min="0" step=".01" value="<?= e($p['land_area'] ?? '') ?>"></label><label class="field"><span>Neighborhood (optional)</span><select name="neighborhood_id"><option value="">No collection selected</option><?php foreach (\Aurelle\Database::all('SELECT id,name FROM neighborhoods') as $n): ?><option value="<?= $n['id'] ?>" <?= ($p['neighborhood_id'] ?? 0)==$n['id']?'selected':'' ?>><?= e($n['name']) ?></option><?php endforeach ?></select></label><label class="field"><span>Video link (optional)</span><input type="url" name="video_url" value="<?= e($p['video_url'] ?? '') ?>" placeholder="https://www.youtube.com/…"></label><label class="field"><span>Virtual tour link (optional)</span><input type="url" name="tour_url" value="<?= e($p['tour_url'] ?? '') ?>" placeholder="https://my.matterport.com/…"></label></div><div class="check-list"><label><input type="checkbox" name="link_authorization" <?= !empty($p['video_url']) || !empty($p['tour_url'])?'checked':'' ?>> I have permission to share these optional external links.</label></div><p class="tiny">Only configured HTTPS video/tour hosts are allowed. External links open separately; no third-party scripts are embedded.</p>
